// Security reviews and design tasks. These acceptance scenarios are manual
// evaluation criteria; the Practice workspace does not execute security code.
const review = (topic,difficulty,slug,title,prompt,objective,requirements,cases,hints,answer,followUp) => ({
    id:`backend-auth-${slug}-v1`,career:'Backend Developer',phase:'Authentication & Security',topic,title,difficulty,
    kind:'written',language:'Security technical response',
    estimatedTime:difficulty==='Easy'?'20–30 minutes':difficulty==='Medium'?'35–50 minutes':'50–75 minutes',
    problemStatement:prompt,simplerProblem:objective,
    learningObjectives:[objective,`Evaluate the ${topic} control against the supplied failure scenario.`],
    prerequisites:['HTTP request/response flow','Verified identity and server-side data ownership'],conceptsToReview:[topic],
    requirements,examples:cases.map(([input,output])=>({input,output,explanation:objective})),
    tests:cases.map(([input,expected],i)=>({name:`Acceptance scenario ${i+1}`,input,expected})),
    hints,approach:`${hints[0]} ${hints[1]} Trace the trust boundary and verify the accepted and rejected outcomes before choosing the control.`,
    walkthrough:cases.map(([input,output])=>`${input} → ${output}`).join('\n'),
    solutionCode:answer,solutionLines:answer.split('\n').filter(Boolean),completionCriteria:requirements,
    commonMistakes:[],starterCode:'Threat and trust boundary:\n\nProposed control:\n\nAcceptance evidence and limitations:\n',followUp
});

export const BACKEND_AUTH_SECURITY_PRACTICE = [
    review('JWT','Easy','jwt-verify','Verify an access token before trusting its subject',
        'A JWT middleware decodes a bearer token and assigns payload.sub to req.user without verifying it. Design an RS256 access-token verifier for a configured public key, issuer career-auth, and audience career-api. Require subject and expiration claims as part of the application contract.',
        'Separate decoding from signature and claim verification.',
        ['Allow only RS256 with a trusted configured key.','Validate issuer, audience, expiration, and a nonempty string subject; reject missing required claims.'],
        [['Valid signed token with expected claims and future exp','Return verified claims for subsequent authorization.'],['Payload edited without a new valid signature','Reject before any protected service call.']],
        ['Decoding only parses attacker-supplied data.','Configure verification policy on the server instead of selecting it from token content.'],
        "function verifyAccess(token,publicKey) { const claims=jwt.verify(token,publicKey,{algorithms:['RS256'],issuer:'career-auth',audience:'career-api'}); if (!claims || typeof claims !== 'object' || typeof claims.sub !== 'string' || !claims.sub.trim() || !Number.isFinite(claims.exp)) throw new Error('Invalid claims'); return claims; }\nHere jwt is the maintained jsonwebtoken library and publicKey is trusted deployment configuration. Its verify checks the signature and registered constraints, including expiry when present; the explicit check makes exp required. Catch failures at the authentication boundary and return a generic 401 without logging the token. A verified subject still requires resource authorization.",
        'Add a test for a valid signature but absent expiration.'),
    review('JWT','Easy','jwt-expiry','Apply expiration in seconds with bounded clock skew',
        'A JWT has exp=2000 in NumericDate seconds. The verifier clock is controlled in tests. Define acceptance at seconds 1999 and 2000 with zero tolerance, then explain a small configured tolerance without treating it as a way to accept indefinitely expired tokens.',
        'Test token lifetime boundaries using the verifier clock.',
        ['Reject at now >= exp when tolerance is zero.','Use a small justified clock tolerance and monitor clock synchronization.'],
        [['now=1999, exp=2000, zero tolerance','May pass expiration validation if all other checks pass.'],['now=2000, exp=2000, zero tolerance','Reject as expired.']],
        ['JWT NumericDate is seconds, unlike Date.now milliseconds.','Inject the verification clock in tests rather than waiting for real-time expiry.'],
        'Use the library expiration check with an explicitly controlled test clock. Convert application milliseconds to seconds when needed; do not compare raw Date.now() to exp.\nAt zero tolerance a token is expired when the verifier time reaches exp. A small configured tolerance accommodates measured clock skew but extends the practical acceptance window. Require exp, cap issued lifetimes, and never enable ignoreExpiration to make tests or deployment failures disappear. Validate nbf when present as well.',
        'Write separate tests for a future nbf claim.'),
    review('JWT','Easy','jwt-public-payload','Keep secrets out of signed token claims',
        'A JWT issuer includes a database password and private user notes in a signed access-token payload because the signature supposedly hides them. Review which information a bearer can read and propose a minimal identity payload without changing the authorization service into a client-trusted decision.',
        'Distinguish integrity protection from confidentiality.',
        ['Remove secrets and unnecessary personal data from claims.','Keep private record lookup and permission checks on the server.'],
        [['Recipient inspects a normal signed JWT payload','Claims are readable; signature is not encryption.'],['Client changes role=admin in its local token copy','Server rejects the invalid signature and never trusts the edited role.']],
        ['Base64url encoding is reversible.','Minimize claims even when transport uses TLS.'],
        'Issue only necessary claims such as issuer, audience, subject, issued-at, expiration, and an operation-appropriate token identifier. Retrieve sensitive data through authenticated scoped APIs instead of placing it in the token.\nA signed JWT protects integrity when verified; it does not conceal its payload. TLS protects transport, not every recipient, browser extension, log, or storage location. If application encryption is needed, choose an established protocol with key management rather than inventing claim obfuscation.',
        'Define a token-redaction rule for access logs.'),
    review('JWT','Medium','jwt-audience','Reject a token issued for a different service',
        'A JWT signed by the same issuer is used by both the reporting API and the billing API. A reporting access token is presented to billing. Design audience and token-purpose validation so sharing a signing authority does not make tokens interchangeable.',
        'Bind verified tokens to their intended recipient and purpose.',
        ['Require the billing audience at the billing verifier.','Use a separate explicit policy for access tokens versus refresh or identity tokens.'],
        [['Valid signature but aud=reports-api at billing','Reject despite a trusted issuer.'],['Billing access token with matching issuer, audience, purpose, and valid lifetime','Authenticate then enforce billing permissions separately.']],
        ['A signature identifies a signing authority, not every permitted use.','Keep verification profiles distinct by token type.'],
        'Configure the billing verifier with its exact accepted issuer, algorithm/key policy, and billing-api audience. Require the issued access-token purpose/type contract and required claims rather than accepting any signed blob from that issuer.\nDo not use a refresh token or identity token as an API access token. Support audience arrays using the verifier semantics but keep the server allowlist narrow. Test wrong audience, wrong purpose, wrong issuer, and a valid token without letting any rejected request reach billing services.',
        'Specify how a multi-audience token affects least privilege.'),
    review('JWT','Medium','jwt-revocation','Define logout behavior for short-lived access tokens',
        'A JWT application clears browser storage on logout but a copied access token remains valid until expiration. Define a logout contract comparing short access-token lifetime with server-side revocation state, including the behavior when a revocation store cannot be checked.',
        'State the actual revocation window rather than promising client deletion invalidates copies.',
        ['Revoke the refresh/session credential on logout.','Choose a bounded access-token window or a mandatory server revocation check with a documented outage policy.'],
        [['Copied token after browser storage is cleared','It may remain usable until expiry unless server policy explicitly revokes it.'],['Server checks a revoked session ID','Reject access even if signature and exp are valid.']],
        ['A token copy exists independently of the original browser storage.','Immediate revocation adds state and availability dependencies.'],
        'Revoke the refresh/session record server-side and clear the client credential. If access tokens are self-contained and not checked against state, document their remaining validity window and keep it appropriately short.\nFor sensitive APIs, check a session version or bounded denylist keyed by verified jti/session ID until expiry. Define fail-closed behavior for required checks and monitor revocation-store health. Do not claim immediate revocation while allowing checks to fail open silently. Avoid storing raw bearer tokens as denylist keys.',
        'Design password-change behavior for all active sessions.'),
    review('JWT','Medium','jwt-refresh-rotation','Detect a reused refresh credential',
        'A JWT login uses a long-lived refresh credential. Two requests attempt to use the same refresh value. Design rotation with atomic consumption, durable session-family state, and a deliberate policy for benign concurrent refreshes versus suspected replay.',
        'Make refresh rotation a replay-aware state transition.',
        ['Store only a secure verifier/digest of high-entropy refresh credentials.','Atomically consume the prior credential and issue one successor under a bounded replay policy.'],
        [['One refresh value is submitted twice','Only the allowed atomic transition wins; replay follows a defined session-family response.'],['Response is lost after rotation','Recovery must not accept unlimited predecessor reuse.']],
        ['Rotation without atomicity can create multiple valid descendants.','Coordinate client refreshes and define any narrow grace policy explicitly.'],
        'Generate high-entropy opaque refresh credentials, retain protected verifiers and family metadata, and atomically replace the currently valid credential on use. A failed predecessor check triggers the documented replay policy, commonly revoking the family and requiring reauthentication.\nSerialize browser refresh attempts where practical. If supporting lost-response recovery, bind and limit any grace/retry behavior rather than permitting unbounded reuse. Set absolute/idle lifetimes and clear/revoke state on logout. Never send refresh values into logs or ordinary analytics.',
        'Describe how an attacker and legitimate client racing a refresh affect recovery.'),
    review('JWT','Hard','jwt-key-rotation','Rotate signing keys without trusting token-directed URLs',
        'A JWT verifier uses kid to download an arbitrary key URL named by the token. Design a trusted issuer key-set lookup with bounded caching, unknown-key handling, and a rotation overlap that does not turn token input into an SSRF destination.',
        'Keep key discovery inside server-configured trust boundaries.',
        ['Resolve kid only within a configured issuer key set.','Bound fetch rate/cache lifetime and never derive arbitrary network URLs or filesystem paths from token headers.'],
        [['Token contains an attacker URL in jku or kid','No arbitrary fetch; reject an unknown/untrusted key reference.'],['Issuer adds a new key during planned overlap','Refresh trusted metadata under a bounded policy and verify with the matching allowed key.']],
        ['A header is untrusted until verification and still cannot define its own trust anchor.','Unknown-key bursts need throttling to avoid a fetch-amplification attack.'],
        'Configure issuer-to-JWKS endpoints and accepted key types/algorithms out of band. Use kid as a bounded lookup key within the trusted set, reject duplicate/ambiguous entries, and verify issuer/audience/lifetime after signature validation.\nCache with bounded lifetime and one controlled refresh path for unknown keys. Retain old verification keys only for the required valid-token overlap; compromised keys need a separate emergency revocation decision. Respect trusted metadata transport controls and never follow token-supplied arbitrary key destinations.',
        'Design the behavior during a trusted JWKS endpoint outage.'),
    review('JWT','Hard','jwt-algorithm-confusion','Keep asymmetric and symmetric verification policies separate',
        'A JWT gateway supports both RS256 and HS256 for different integrations and chooses the verifier algorithm from an incoming header. Review an algorithm-confusion risk and design independent issuer/key profiles without recommending a public key as an HMAC secret.',
        'Prevent untrusted algorithm selection from changing key meaning.',
        ['Bind allowed algorithm and key type to the configured integration.','Reject none and unsupported algorithms regardless of header preference.'],
        [['RS256 integration receives HS256 token','Reject; do not reinterpret the RSA public key bytes as an HMAC secret.'],['HS256 integration has a strong independent secret','Verify only under that integration’s explicit policy and intended claims.']],
        ['Keys are not interchangeable just because both are byte sequences.','Avoid a fallback chain that tries every algorithm until one succeeds.'],
        'Create separate verifier profiles per trusted issuer/integration with an explicit algorithm allowlist and compatible key material. For an RS256 profile allow RS256 only and load a trusted RSA verification key; for an HS256 profile use a separate cryptographically random shared secret with limited holders.\nDo not enable insecure key-type bypasses or accept alg=none. Test header-algorithm substitution, wrong key types, and cross-profile tokens using a maintained library. Anyone holding an HMAC verification secret can also mint tokens, which changes the trust model compared with public-key verification.',
        'Explain why sharing one HMAC secret across many services widens the signing boundary.'),
    review('JWT','Hard','jwt-stale-permissions','Handle a valid token after membership is revoked',
        'A JWT contains tenant membership and an administrator role valid for 30 minutes. The user loses that membership while the token is still signed and unexpired. Design a high-risk action policy that prevents stale permissions while retaining a deliberate latency and availability budget.',
        'Separate durable authentication evidence from current authorization state.',
        ['Check current membership/permission state for the sensitive action.','Define cache freshness, invalidation, and denial behavior when required state is unavailable.'],
        [['Removed administrator presents an otherwise valid token','Sensitive action is denied by the current policy.'],['Authorization cache is stale after a revocation event','Bound the window or bypass it for the high-risk check; do not promise instantaneous revocation otherwise.']],
        ['Token claims are snapshots of what the issuer knew at issuance.','Short token lifetime reduces a window but does not equal an immediate current-state check.'],
        'Verify the token first, then resolve current subject/tenant membership and the exact action permission through an authoritative policy service or version-aware state. For high-risk operations use a required freshness policy and deny when that decision cannot be established.\nDocument bounded cache staleness, event invalidation, and session/permission versions. Recheck conditions atomically with the protected write when the invariant can race. Log controlled decision context without bearer credentials. A valid signature alone never proves current tenant access.',
        'Define how to test revocation racing a protected write.'),

    review('Sessions','Easy','session-cookie-flags','Configure a host-only HTTPS session cookie',
        'A Sessions review finds a production authentication cookie readable by JavaScript, sent over HTTP, and scoped to every sibling subdomain. Specify flags for an HTTPS same-site application and explain which attack each flag addresses without claiming any flag prevents all XSS or CSRF.',
        'Separate cookie transport, script access, scope, and cross-site behavior.',
        ['Use Secure, HttpOnly, Path=/ and omit Domain for host-only scope.','Choose an explicit SameSite policy and retain CSRF defenses for mutations.'],
        [['Production HTTPS response sets __Host-sid','Secure; HttpOnly; Path=/; SameSite=Lax, with no Domain under the chosen same-site contract.'],['Injected JavaScript attempts to read the cookie','HttpOnly blocks direct cookie access but does not stop malicious script issuing authenticated actions.']],
        ['A __Host- prefix requires Secure, Path=/, and no Domain.','SameSite is defense in depth rather than universal authorization or CSRF protection.'],
        'Set a high-entropy opaque session ID in an appropriately scoped cookie. For this same-site contract use __Host-sid with Secure, HttpOnly, Path=/, SameSite=Lax and no Domain; enforce HTTPS and a bounded lifetime.\nKeep state-changing actions protected against CSRF with a validated token/origin strategy suited to the application. Secure affects transport, HttpOnly affects script reading, and SameSite affects cross-site sending. None makes an XSS-compromised page trustworthy. Do not silently disable production protections to accommodate a misconfigured proxy.',
        'Compare Lax and Strict against an external-link sign-in workflow.'),
    review('Sessions','Easy','session-fixation','Rotate session identity after login',
        'A Sessions implementation upgrades an anonymous session into an authenticated session without changing its ID. An attacker previously induced the victim to use that known ID. Design the login transition and specify which pre-login state is safe to carry forward.',
        'Prevent fixation by replacing session identifiers at privilege transitions.',
        ['Regenerate the session ID after successful credential verification.','Invalidate the predecessor and copy only allowlisted non-sensitive state.'],
        [['Anonymous session becomes authenticated','A new unpredictable ID is issued and the old ID cannot access the authenticated session.'],['Attacker replays the old anonymous ID','It does not inherit the victim’s login.']],
        ['Authentication changes the privileges attached to a session.','Rotating a cookie without invalidating its predecessor is insufficient.'],
        'After credentials are verified, regenerate the session through the session store/framework API, invalidate the prior identifier, and then attach the verified account ID to the new session. Await persistence before confirming login.\nCopy only explicitly allowed pre-login preferences or workflow state. Do not carry a client-supplied owner, role, or session identifier into trusted state. Regenerate again for relevant privilege changes and test old/new IDs with separate clients.',
        'Specify safe handling when session regeneration or persistence fails.'),
    review('Sessions','Easy','session-logout','Invalidate the server record on logout',
        'A Sessions logout endpoint only removes the browser cookie. A copied cookie still authenticates because the server session remains active. Design server-side invalidation plus cookie clearing, including a repeated logout request and a storage failure.',
        'Make logout revoke server authority rather than merely changing browser appearance.',
        ['Destroy or revoke the server session and clear the cookie with matching scope.','Do not claim confirmed revocation when required session-store invalidation fails.'],
        [['Normal logout then replay of copied cookie','Server refuses the revoked session.'],['Logout is repeated after revocation','A safe idempotent outcome does not recreate a session.']],
        ['A bearer cookie copy is independent of the current browser cookie jar.','Cookie name, path, and Domain scope must match when clearing.'],
        'Revoke/destroy the current server session using its verified identifier, then clear the matching cookie and return the documented logout result. Protect a cookie-authenticated logout mutation against unwanted cross-site triggering as required by policy.\nOn store failure clear the local cookie if appropriate but report uncertainty or failure rather than asserting global revocation. Do not log the raw cookie. An all-devices logout is a different operation requiring account-level session invalidation and stronger confirmation.',
        'Add a test proving another browser’s independent session is unaffected by current-device logout.'),
    review('Sessions','Medium','session-deadlines','Enforce idle and absolute expiry on the server',
        'A Sessions app extends a cookie forever on every request. Specify a 20-minute idle limit and an 8-hour absolute lifetime measured from login. Explain what the server must check even if a client sends a cookie beyond its displayed browser expiry.',
        'Bound both inactivity and total authenticated session lifetime.',
        ['Track createdAt and lastActivity in authoritative session state.','Reject at either server-side deadline and do not reset the absolute origin on routine activity.'],
        [['Last activity 21 minutes ago but login only one hour ago','Reject idle-expired session.'],['Continuous activity for more than eight hours','Require reauthentication despite recent activity.']],
        ['A client-controlled request cannot choose its own last-active timestamp.','Cookie lifetime is not a substitute for a server-side validity rule.'],
        'At admission compare server time with lastActivity+20 minutes and createdAt+8 hours; reject when either bound is reached. Advance activity under a controlled server policy and expire stored records with a bounded cleanup mechanism.\nSet cookie expiry consistent with the remaining server lifetime, but enforce deadlines independently of cookie presence. Use consistent clocks, define whether background polling refreshes activity, and avoid writes on every tiny request if coarse updates meet the policy. Test exact boundaries with an injected clock.',
        'Define how a step-up authentication timestamp differs from the original login time.'),
    review('Sessions','Medium','session-distributed','Share session authority across API replicas',
        'A Sessions application stores sessions only in each process. Requests alternate between two replicas, and a restart logs users out inconsistently. Design a shared store with TTL and an outage policy; do not treat sticky routing as sufficient persistence or revocation.',
        'Make session validity consistent across replicas.',
        ['Use an access-controlled shared store with bounded expiry and opaque IDs.','For protected requests fail closed when required validity cannot be established.'],
        [['User logs in on replica A then requests replica B','B resolves the same active server session.'],['Session store is unavailable','Protected operations do not silently accept an unchecked client identity.']],
        ['A signed cookie cannot reconstruct lost process-only session records.','Shared authority adds availability and latency dependencies that need monitoring.'],
        'Use a production session-store adapter shared by replicas, with expiry, TLS/network controls, credential scoping, and capacity monitoring. Store minimal principal/session metadata and keep cryptographic signing keys under managed rotation.\nChoose controlled error handling when store checks fail; do not bypass authentication to preserve a success rate. Sticky routing may reduce lookups or mask a bug temporarily but does not solve instance loss or global revocation. Test restart, cross-replica access, expiry, and store failure.',
        'Specify a migration plan for existing in-process sessions without asserting they can be recovered after process loss.'),
    review('Sessions','Medium','session-csrf','Protect a cookie-authenticated preference update',
        'A Sessions endpoint accepts a browser cookie and mutates preferences. A malicious site can submit a cross-site request. Design CSRF validation for the mutation, explaining why HttpOnly and a hidden frontend button do not prove the request was intended by the user.',
        'Require an independent indication of same-application request intent.',
        ['Use a session-bound unpredictable synchronizer token or a correctly implemented signed double-submit design.','Validate the token and an appropriate Origin policy before mutation; retain SameSite defense in depth.'],
        [['Authenticated request with a valid session-bound CSRF token','May proceed after normal authorization and input validation.'],['Cookie present but token missing/invalid from another origin','Reject before the preference write.']],
        ['Browsers attach cookies automatically under their cookie policies.','A token delivered through an application page must not be exposed through permissive cross-origin reads.'],
        'For a server-session application, generate a cryptographically random CSRF token associated with the session and return it through an authenticated same-application channel. Require it in a custom header or form field and validate it before mutating state; use timing-safe comparison where appropriate.\nCheck a strict Origin policy on unsafe requests with a deliberate fallback/rejection rule for absent headers. Use SameSite and safe HTTP methods as additional controls. XSS can undermine browser CSRF defenses, so prevent injection separately; HttpOnly alone is not sufficient.',
        'Test a cross-site form submission and a legitimate application fetch.'),
    review('Sessions','Hard','session-revocation-race','Prevent an in-flight request from resurrecting logout',
        'A Sessions request reads a session, performs slow work, and later writes its cached session state. Meanwhile logout destroys the store record. The late write recreates the session. Design versioned/tombstoned validity and a store update contract that prevents resurrection.',
        'Handle concurrent session updates against revocation state.',
        ['Do not let ordinary session save recreate a revoked identifier.','Use an atomic version/validity condition or store semantics that preserve revocation until all copies expire.'],
        [['Logout wins before a delayed session save','The stale save cannot restore authenticated validity.'],['Two active requests update harmless session data','Resolve their updates without weakening expiry or revocation rules.']],
        ['Deletion alone may be reversed by a later unconditional upsert.','Revocation state needs a lifetime at least as long as the credentials it invalidates.'],
        'Represent session validity/version explicitly and make refresh/save conditional on the session still being active with the expected version. Logout atomically marks it revoked or advances an authoritative account/session version; stale writes must fail rather than upsert.\nKeep tombstones/version evidence for the required remaining credential window and define cleanup safely. Integration-test delayed writes across replicas and the real store adapter. Rejecting future admissions does not undo already committed business actions from an in-flight request; high-risk writes may need a fresh transactional permission check.',
        'Document the exact boundary at which a request is considered authorized to commit.'),
    review('Sessions','Hard','session-step-up','Require recent proof for changing recovery credentials',
        'A Sessions user signed in hours ago and wants to change account recovery email. Design step-up authentication tied to this action, resisting reuse of an old proof for another account or a different high-risk operation.',
        'Bind fresh authentication evidence to a scoped sensitive action.',
        ['Require recent verified credentials or appropriate MFA and protect the mutation against CSRF.','Bind short-lived single-use proof to session, actor, and action; revoke it on relevant session changes.'],
        [['Fresh proof for current session and recovery-email action','Permit only the validated authorized action within its deadline.'],['Proof copied to another session or replayed after use','Reject without changing recovery details.']],
        ['An active login session does not establish recent human presence.','Proof expiry alone does not prevent replay during the acceptance window.'],
        'Challenge with the account’s configured strong authentication method and issue a bounded action-specific proof after verification. Store/validate actor, session, purpose, expiry, and a single-use nonce atomically with consuming the proof and changing the protected state where feasible.\nRotate session identity after privilege-sensitive transitions, notify through a trusted existing channel, and define recovery if a factor is unavailable. Avoid downgrading to weak knowledge-based questions. Use rate limits and avoid logging proofs or recovery secrets.',
        'Define how a concurrent password reset invalidates pending step-up proofs.'),
    review('Sessions','Hard','session-cookie-proxy','Keep secure cookies working behind a trusted TLS proxy',
        'A Sessions deployment terminates TLS at an ingress. Secure cookies are not being issued as expected, and someone proposes disabling Secure globally. Design proxy trust and external HTTPS handling without letting direct clients spoof X-Forwarded-Proto.',
        'Preserve transport security across a verified proxy boundary.',
        ['Trust only the actual ingress path and sanitize forwarded headers at the edge.','Keep Secure production cookies and block unintended direct backend access.'],
        [['Trusted ingress forwards a sanitized HTTPS indication','Application can establish the correct external scheme and issue the secure cookie.'],['Untrusted direct request supplies X-Forwarded-Proto:https','It cannot choose the trust outcome.']],
        ['Proxy trust is a network topology decision, not a convenience boolean.','Disabling Secure treats the symptom by weakening the authentication boundary.'],
        'Configure framework trust-proxy policy for verified ingress addresses/routes and require the ingress to overwrite untrusted forwarding headers. Restrict direct backend access and ensure public HTTP redirects/enforcement do not expose credentials.\nRetain Secure, HttpOnly, appropriate SameSite, and host/path scope. Test external HTTPS, direct HTTP, spoofed forwarded chains, and different ingress paths. A fixed hop count is safe only if every permitted path has the assumed topology. Maintain a separate local-development policy without weakening production.',
        'Add deployment checks for cookie flags and redirect behavior.'),

    review('Password Hashing','Easy','password-kdf','Choose a password-specific storage scheme',
        'A Password Hashing review finds plain SHA-256 digests stored for user passwords. Explain offline guessing risk and select a maintained Argon2id password-hashing implementation with per-password random salts and deployment-benchmarked parameters, rather than designing a custom cryptographic scheme.',
        'Use an adaptive password KDF instead of a fast general-purpose digest.',
        ['Select Argon2id with a measured memory/time policy and a maintained implementation.','Store its encoded hash/parameters, never plaintext or reversible password encryption as the normal verifier.'],
        [['Two users choose the same password','Independent random salts produce different encoded password hashes.'],['Database hashes are stolen','KDF cost slows guesses but does not make weak passwords immune to cracking.']],
        ['Fast digests are designed for throughput, which helps offline guessing.','Benchmark the cost under realistic authentication concurrency and memory limits.'],
        'Use a maintained password-hashing library that creates a fresh random salt and encodes algorithm, salt, cost, and derived value. Prefer Argon2id under a reviewed memory/time configuration; scrypt can be appropriate where Argon2id is unavailable.\nMeasure resource use and choose a supported baseline policy rather than claiming one universal cost is optimal forever. Never log passwords. Add online abuse controls separately: password hashing protects stored verifiers, not all login traffic. Avoid implementing Argon2 or inventing a sequence of ordinary hash calls.',
        'Describe a parameter-upgrade policy for existing encoded hashes.'),
    review('Password Hashing','Easy','password-verify','Verify with the password-hashing library',
        'A Password Hashing login computes a fresh salted hash and compares its text with the stored encoded hash. Every login fails because the new salt changes the result. Describe a correct verification call and a generic failure response without exposing stored verifiers.',
        'Verify against the stored salt and parameters rather than generating a new verifier.',
        ['Pass the encoded stored hash and supplied password to the library verify API.','Return a generic authentication failure for wrong credentials and keep verifiers out of responses.'],
        [['Correct password and a valid stored Argon2id hash','Library verification succeeds using the stored parameters.'],['Different password','Verification fails; do not return a password hint or the stored hash.']],
        ['The encoded hash contains the information required to repeat the KDF.','Use the maintained verification API rather than manually comparing ordinary strings.'],
        'Use the library’s documented verify(encodedHash, suppliedPassword) contract, awaiting its result and handling malformed stored data as a controlled operational failure. Do not call hash(password) with a fresh salt and compare encoded strings.\nKeep all secret values out of logs, analytics, and public errors. A login flow should avoid obvious account-existence differences and use rate limits; where needed perform a bounded dummy verification for unknown users under the same cost policy rather than returning immediately.',
        'Test valid, wrong-password, and malformed-stored-hash paths.'),
    review('Password Hashing','Easy','password-no-truncate','Define password length and Unicode handling deliberately',
        'A Password Hashing API trims whitespace and slices input to 72 characters before hashing. Users unexpectedly authenticate with a different password. Define a documented input contract preserving the intended password, including byte limits and algorithm-specific truncation concerns.',
        'Avoid silently changing or truncating secret input.',
        ['Do not trim or silently truncate submitted passwords.','Validate supported length/encoding before the KDF and reject over-limit values explicitly.'],
        [['Password has intentional leading spaces','Those spaces remain part of the password under this contract.'],['Input exceeds the supported byte budget','Reject explicitly rather than hashing only a prefix.']],
        ['Character count and UTF-8 byte count differ.','Legacy bcrypt limits are byte-oriented; switching encodings or prehashing needs a reviewed migration.'],
        'Choose a documented Unicode/encoding policy and generous but bounded input size, then apply it consistently at registration and verification. Preserve whitespace and reject rather than silently truncate unsupported input.\nUse a KDF that supports the required input domain. If maintaining legacy bcrypt, account for its 72-byte input limit and plan a migration instead of cutting text at 72 characters or bolting on an unreviewed prehash. Avoid normalization changes that lock out existing users without explicit versioning.',
        'Create tests using multibyte characters and two long passwords sharing a prefix.'),
    review('Password Hashing','Medium','password-upgrade','Upgrade a weak verifier after a successful login',
        'A Password Hashing database contains older low-cost hashes and newer stronger encoded hashes. Design opportunistic rehashing after successful verification, without forcing a weak scheme for all accounts or overwriting a concurrent password change.',
        'Migrate verifiers with explicit version and concurrency checks.',
        ['Verify under the stored supported scheme, then rehash only after success.','Replace conditionally on the original verifier/version so a concurrent reset is not undone.'],
        [['Successful login with an outdated supported hash','Generate a new current-policy hash and conditionally save it.'],['Password reset changes the record during rehash','The stale replacement fails its condition rather than restoring the old password.']],
        ['A hash cannot generally be converted to another password KDF without the password.','Compare-and-swap protects the password lifecycle from late writes.'],
        'Parse only supported encoded formats with bounded parameters, verify the submitted password, then determine whether algorithm/cost needs upgrade. Generate a current-policy verifier from that successfully supplied password and update where the credential version or old verifier still matches.\nDo not store plaintext for later migration or blindly overwrite the row. Unsupported/compromised schemes may require a forced reset policy. Use an absolute migration plan for dormant accounts rather than claiming every user will eventually log in.',
        'Specify how upgraded verifiers interact with session revocation policy.'),
    review('Password Hashing','Medium','password-pepper','Separate an optional pepper from the password database',
        'A Password Hashing architecture proposes a global pepper stored beside hashes in the same database. Explain what separate secret custody can add, then design a reviewed pepper strategy and recovery/rotation trade-offs without claiming pepper replaces salts or a password KDF.',
        'Treat a pepper as a separately managed optional secret with lifecycle cost.',
        ['Keep any pepper in a secret-management boundary separate from database records.','Retain per-password salts and an adaptive KDF and plan loss/rotation before deployment.'],
        [['Attacker obtains only the verifier database','A separately held pepper can add a barrier under the chosen threat model.'],['Pepper is lost or compromised','Verification/recovery may require a reset or staged supported-key transition.']],
        ['A public per-record salt and a shared secret serve different purposes.','Use a reviewed library/design rather than inventing ad hoc concatenation rules.'],
        'Evaluate a vetted pepper integration, such as a documented supported secret-input mechanism or a reviewed keyed stage around the KDF. Store only a pepper version reference with records and keep the secret in managed custody with strict access and auditing.\nPreserve unique salts and KDF cost. Plan how old pepper versions are verified during transition and whether compromise mandates resets; hashes generally cannot be re-peppered without the password or a designed recovery process. Co-locating the pepper with the database defeats the intended separate-compromise benefit.',
        'Describe availability behavior if the secret manager is unavailable.'),
    review('Password Hashing','Medium','password-bcrypt-migration','Migrate a bcrypt estate without losing input semantics',
        'A Password Hashing service has legacy bcrypt verifiers and wants Argon2id. Some legacy passwords exceed bcrypt’s input limit. Design algorithm-version detection and a safe login/reset migration that does not claim it can recover the original password from the hash.',
        'Preserve verification compatibility while eliminating silent legacy ambiguity.',
        ['Keep a bounded allowlist of supported stored formats and verify using their documented semantics.','Rehash a successfully supplied password under the new scheme only with a deliberate long-input policy.'],
        [['Ordinary legacy password verifies successfully','Create a new salted Argon2id verifier conditionally after success.'],['Legacy verification accepts several long inputs sharing a processed prefix','Do not assume which full input the user originally chose; require an appropriate reset/reauthentication policy.']],
        ['The old verifier proves only the input semantics of the old algorithm.','Credential migration can change which strings authenticate.'],
        'Version supported formats and route verification accordingly, with bounded cost parameters. After successful unambiguous legacy verification, create a current-policy verifier and conditionally replace the old record.\nFor ambiguous long-input behavior, use an explicit credential-reset flow appropriate to the risk instead of silently binding the account to whichever suffix was submitted first. Preserve rate limits and generic errors. Do not bulk transform bcrypt strings into Argon2id and claim equivalent password verification; a hash of a hash has a different security and input contract.',
        'Define tests for ASCII and multibyte inputs around the legacy byte limit.'),
    review('Password Hashing','Hard','password-resource-budget','Keep password verification from exhausting server memory',
        'A Password Hashing endpoint runs a memory-hard KDF for every anonymous request with unlimited concurrency. Under a burst the service runs out of memory. Design bounded admission, measured KDF parameters, and overload behavior without weakening all password hashes to a fast digest.',
        'Budget expensive authentication work under adversarial load.',
        ['Bound in-flight KDF jobs and queued work using measured per-job memory and latency.','Combine limits with account/network abuse controls and return controlled overload responses.'],
        [['KDF peak memory times active jobs exceeds process budget','Reduce allowed concurrency or provision capacity; do not start every job immediately.'],['Work queue reaches capacity','Reject or defer according to a bounded policy without retaining unlimited plaintext passwords.']],
        ['An intentionally expensive verifier needs explicit capacity planning.','A rate limit alone does not bound simultaneous slow jobs.'],
        'Measure per-job peak memory/CPU and choose a concurrency ceiling leaving room for the rest of the process. Apply bounded queue/admission controls before starting expensive verification and constrain password input size under a published policy.\nUse separate account and source abuse budgets, deadlines, monitoring, and a controlled busy outcome. Keep secrets out of persistent queues/logs and minimize their lifetime in memory. Do not claim aborting an HTTP request necessarily stops a native KDF already running; count the job until it actually settles. Benchmark latency and memory together before changing KDF cost.',
        'Design a load test proving peak memory remains bounded during a rejected burst.'),
    review('Password Hashing','Hard','password-malicious-parameters','Bound the parameters accepted from encoded hashes',
        'A Password Hashing migration imports encoded verifier records from an external source. One record advertises an extreme memory/time cost or malformed encoding. Design import validation and safe verification policy without treating the stored hash text as trustworthy executable configuration.',
        'Validate verifier format and cost before allocating expensive work.',
        ['Accept only approved algorithm versions and bounded parameter ranges.','Quarantine malformed/out-of-policy records and define a reset path without logging secret material.'],
        [['Approved encoded hash within resource policy','May enter the bounded verifier pool.'],['Hash claims enormous memory cost','Reject/quarantine before allocating that memory.']],
        ['A database value can be corrupted or imported from an untrusted boundary.','Lower and upper cost bounds address weak verifiers and resource exhaustion separately.'],
        'At import and verification boundaries use a maintained format parser and an allowlisted policy for algorithm, version, salt/digest structure, and resource costs. Check both minimum accepted security and maximum safe resource use before verification.\nQuarantine invalid records with a safe record identifier and require a controlled recovery/reset process. Do not normalize an arbitrary malformed hash into a successful login or echo it to the client. Distinguish operational corruption from a wrong password internally while keeping public authentication errors non-disclosing.',
        'Specify how to test parser rejection without actually allocating the claimed memory.'),
    review('Password Hashing','Hard','password-enumeration','Reduce account enumeration without creating a denial-of-service oracle',
        'A Password Hashing login immediately returns unknown-user errors but performs a costly KDF for existing accounts. Design a response/timing policy using a current-policy dummy verifier, abuse limits, and bounded work, while explaining why perfect indistinguishability cannot be asserted from one timing test.',
        'Avoid obvious account-existence differences while bounding expensive work.',
        ['Use generic public login failures and a controlled dummy verification path for absent accounts where needed.','Apply bounded concurrency and abuse controls to real and dummy work alike.'],
        [['Unknown account and wrong password for known account','Both receive the same public failure contract and comparable intended verification work.'],['Attack floods arbitrary account names','Dummy work is still subject to admission and abuse budgets.']],
        ['Matching response text alone does not remove a large timing difference.','Equalizing work without admission control can amplify resource exhaustion.'],
        'Normalize account identifiers consistently, fetch a scoped account, and select its supported verifier or a precomputed current-policy dummy verifier. Run bounded verification, then fail generically when the account was absent regardless of the dummy result.\nKeep status/body behavior and recovery messaging consistent, and apply account/source controls without exposing account existence through distinct lockout details. Measure distributions under realistic load rather than claiming mathematically equal response times. Review old/new KDF cost differences, network jitter, logging, and recovery endpoints as part of the same threat model.',
        'Design a test plan comparing timing distributions without using real user passwords.'),

    review('Authorization','Easy','authn-vs-authz','Separate identity verification from permission decisions',
        'An Authorization endpoint assumes any successfully signed-in user can delete any project. Explain the distinction between authentication and authorization and define a project deletion policy for owners only, with a safe unauthenticated response.',
        'Require both verified identity and the specific resource permission.',
        ['Authenticate before using a principal.','Check project ownership or an explicit trusted permission before deletion.'],
        [['No valid authentication','401 and no project mutation.'],['Verified u1 requests deletion of a u2 project','Deny under the documented non-disclosure policy; no mutation.']],
        ['Knowing who sent a request does not prove access to every resource.','Keep the final write scoped to the authorized actor/resource relation.'],
        'First establish a verified principal through the authentication boundary. Then invoke an owner-scoped service/delete predicate such as {_id:projectId,ownerId:principal.id}, or an explicit policy check with equivalent write enforcement.\nReturn the chosen 403 or nonrevealing 404 for inaccessible resources consistently. Do not trust a body ownerId or a hidden UI button as authority. Test allowed-owner, other-owner, absent, and unauthenticated requests and assert the protected write is never called on denial.',
        'Add an explicitly scoped administrator exception and negative tests.'),
    review('Authorization','Easy','authz-role-allowlist','Deny unknown roles and unlisted actions',
        'An Authorization helper grants access unless role equals guest. New roles and missing role values accidentally receive administrator actions. Design a small explicit role/action matrix for viewer reading reports and editor reading/updating reports, with deletion reserved for an administrator.',
        'Use explicit permission allowlists with default denial.',
        ['Unknown/missing roles and actions are denied.','Keep authentication and resource/tenant checks outside and in addition to this role matrix.'],
        [['viewer requests reports:update','Deny.'],['Unrecognized role requests reports:read','Deny rather than defaulting to privilege.']],
        ['Negative lists fail open when the role vocabulary grows.','A Map avoids inherited-object-key surprises in policy lookup.'],
        "const permissions=new Map([['viewer',new Set(['reports:read'])],['editor',new Set(['reports:read','reports:update'])],['admin',new Set(['reports:read','reports:update','reports:delete'])]]); const can=(role,action)=>permissions.get(role)?.has(action)===true;\nResolve roles from verified current authority, not request body fields. This matrix answers only role/action permission: still verify tenant, resource scope, and any action conditions. Test missing values, unknown roles/actions, and explicit allowed pairs.",
        'Introduce a suspended account condition that overrides every allow entry.'),
    review('Authorization','Easy','authz-owner-input','Ignore client-selected ownership during creation',
        'An Authorization create-note controller forwards req.body including ownerId and role to a service. A client chooses another account as owner. Design an input DTO that derives authority from the verified principal and admits only the note fields allowed by the API.',
        'Prevent mass assignment across an ownership boundary.',
        ['Derive ownerId from verified identity and enforce it in the service.','Reject or ignore unknown fields under one explicit policy; never forward privilege fields.'],
        [['Body contains title and ownerId for another user','Under this reject-unknown policy return 400 and do not create.'],['Valid title only from verified u1','Create with ownerId u1.']],
        ['Client input describes requested content, not who it is allowed to impersonate.','Construct a new allowlisted command instead of spreading the body.'],
        'Require the documented note object shape and validate title. Under this contract reject keys outside title/content, then construct {ownerId:principal.id,title:validatedTitle,content:validatedContent}.\nService methods should require the trusted actor/context and preserve the same boundary for non-HTTP callers. Return a public DTO and test privileged/unknown keys, cross-tenant IDs, and valid creation. An administrator impersonation capability, if needed, belongs to a separately authorized audited operation.',
        'Define how an ownership-transfer command differs from ordinary note editing.'),
    review('Authorization','Medium','authz-nested-resource','Scope nested resources to the authorized parent',
        'An Authorization route /teams/:teamId/tasks/:taskId checks team membership but then fetches the task by global ID. A task from another team is exposed. Design one service contract that enforces actor membership and the task-parent relationship.',
        'Bind nested resource access to every relevant relationship.',
        ['Validate current membership in the requested team.','Look up the task with both taskId and authorized team scope.'],
        [['u1 belongs to t1 and task k1 belongs to t1','Allow the requested operation if its role/action conditions pass.'],['u1 belongs to t1 but task k2 belongs to t2','Deny; global task existence does not satisfy the relationship.']],
        ['URL nesting does not automatically enforce database relationships.','Test valid identifiers arranged in an unauthorized combination.'],
        'Pass actor, teamId, taskId, and action into a service that checks current membership and role, then queries/updates the task under teamId plus taskId. Apply the relation in the final write predicate or a concurrency-safe transaction as required.\nKeep denied/missing outcomes consistent to avoid unnecessary existence leaks. A foreign key can support integrity but does not grant actor permission. Test same-team access, cross-team task ID substitution, removed membership, and direct service calls bypassing the router.',
        'Add a reassignment race where the task moves teams during a write.'),
    review('Authorization','Medium','authz-fields','Authorize output fields as well as record access',
        'An Authorization API lets staff view a colleague directory but returns salary and private recovery metadata from full account documents. Design a role-aware output contract with an explicit public projection and a separate restricted detail operation.',
        'Treat field visibility as part of access policy.',
        ['Allowlist directory fields before serialization.','Require a separate justified permission for restricted fields and keep secrets out of all ordinary responses.'],
        [['Ordinary directory reader requests colleagues','Return names and approved public fields only.'],['Reader adds includePrivate=true','The query flag does not grant salary or recovery access.']],
        ['Access to a row is not blanket permission for every stored field.','A new internal database field should not become public automatically.'],
        'Construct directory DTOs from an allowlist such as id/displayName/team and project those fields in the query where practical. For restricted personnel details define a distinct action permission, scope, audit policy, and minimal output.\nDo not select full records and rely on the client to hide sensitive properties. Never return password verifiers, active reset tokens, or raw session secrets. Test future extra database fields and caller-supplied expansion flags so the default response remains narrow.',
        'Specify which fields an audited personnel export may contain.'),
    review('Authorization','Medium','authz-service-boundary','Enforce permissions for background and direct callers',
        'An Authorization check exists only in an HTTP route. A worker calls the same update service directly with a user-supplied project ID, bypassing the route. Design a service-level policy contract and distinguish a user actor from a narrowly scoped service identity.',
        'Enforce authority at the reusable operation boundary.',
        ['Require an explicit verified actor/capability context in the service.','Grant workers only the operations and resource scope they require.'],
        [['Authorized HTTP actor invokes service','Service checks the operation/resource policy and applies the write.'],['Worker receives arbitrary project ID without a scoped capability','Reject rather than using a blanket internal bypass.']],
        ['Internal call paths can still carry untrusted identifiers.','A boolean isInternal flag is not an independently verified authority.'],
        'Move the invariant into a service/policy layer invoked by every entry point. Accept a verified user actor or an explicitly provisioned service identity and check action/resource scope before executing the mutation.\nKeep route checks for early rejection but do not rely on them as the only enforcement. Worker job payloads must be authenticated/authorized at enqueue and rechecked or constrained at execution when permissions can change. Log service identity and decision context without impersonating an arbitrary user.',
        'Define a minimal capability for rebuilding one tenant’s search index.'),
    review('Authorization','Hard','authz-toctou','Prevent a revoked grant from racing a protected write',
        'An Authorization workflow checks a database membership, waits during slow processing, then writes a high-risk change. Membership can be revoked between check and write. Design an invariant protocol that defines whether revocation or the write wins, rather than promising a separate precheck is atomic.',
        'Coordinate authorization state with the effect it protects.',
        ['Use a shared transactional/locking/version protocol that both protected writes and revocations follow.','State the commit/admission boundary and handle stale permission versions as conflicts or denials.'],
        [['Revocation commits before the final protected check/write boundary','The write must not succeed under the old grant.'],['Protected transaction validly commits before revocation','The committed effect is not retroactively rolled back by later revocation.']],
        ['Separate reads can become stale while work is in flight.','Both writers must participate in the chosen serialization protocol.'],
        'For database-coordinated state, lock/version the authoritative grant row and enforce the protected mutation in the same transaction; revocation must acquire/update the same authority under that protocol. Re-evaluate after conflicts and commit only if the required grant still holds.\nIf authority is external, define bounded staleness or an action-specific fresh capability protocol and its revocation limitations instead of claiming a distributed atomic check. Avoid holding locks across slow network work; stage preparation first and validate at commit. Test interleavings with barriers.',
        'Write a two-transaction test proving the declared revocation ordering.'),
    review('Authorization','Hard','authz-policy-cache','Invalidate cached policy without granting on an outage',
        'An Authorization cache stores grants for an hour. Removing an administrator leaves that grant cached, and policy-service failures default to allow. Design versioned cache keys, bounded freshness, and a fail-closed rule for sensitive mutations while considering read availability separately.',
        'Make stale and unavailable policy states explicit.',
        ['Use bounded cache lifetime plus revocation/version propagation under a documented freshness target.','Deny high-risk operations when required current authority cannot be established.'],
        [['Permission removed but old cache entry remains','A version/freshness mechanism prevents claiming immediate revocation without evidence.'],['Policy service times out during a sensitive write','Do not substitute allow; return controlled denial/unavailability.']],
        ['A cache is another authority copy with a consistency contract.','Availability policy can differ by risk but must be explicit and tested.'],
        'Key decisions by subject, tenant, action, resource context, and policy/membership version where applicable. Bound TTL, propagate invalidations, and bypass stale entries for operations requiring fresh authority.\nDefine whether low-risk reads may use a bounded stale decision, while sensitive mutations fail closed on missing required state. Monitor lag and denial/unavailability separately. Do not convert a timeout into permission. Test missed invalidation events, cache restart, policy-version changes, and cross-tenant key isolation.',
        'Define how emergency revocation overrides otherwise acceptable cached reads.'),
    review('Authorization','Hard','authz-capability-link','Scope a share link as a revocable capability',
        'An Authorization design lets users share a private report through a bearer link. The current link exposes the report’s predictable ID indefinitely. Design a high-entropy scoped capability with expiry, revocation, and redacted logging; distinguish view permission from edit or export.',
        'Treat share credentials as limited revocable authority, not obscured resource IDs.',
        ['Generate unpredictable bearer secrets and store protected verifiers with scope/lifetime.','Check current revocation and resource/action constraints on each use.'],
        [['Active link allows view of one report','It grants neither editing nor access to other report IDs.'],['Owner revokes the link or report ownership changes under the policy','The server denies subsequent use according to the defined validity rule.']],
        ['Anyone holding a bearer link may exercise its grant.','URLs can leak through logs, referrers, history, and messages.'],
        'Issue a cryptographically random secret linked to one report, allowed actions, expiry, creator, and revocation state; store a secure digest/verifier rather than the raw secret. Resolve and enforce the grant server-side on every use.\nUse TLS, minimize URL-secret exposure, redact request logs, set suitable referrer/cache policies, and offer owner revocation. Require stronger authentication for sensitive export/edit actions rather than silently widening view scope. Rate-limit invalid lookups and document whether possession alone is an acceptable sharing risk.',
        'Design single-use download behavior with atomic capability consumption.'),

    review('CORS','Easy','cors-exact-origin','Match a credentialed frontend origin exactly',
        'A CORS API intends to trust https://app.example.test but accepts any Origin containing example.test. Review the risk and implement an exact-origin allowlist function without reflecting arbitrary origins or granting a wildcard credentialed response.',
        'Use exact origin tuples rather than substring trust.',
        ['Allow only configured scheme/host/port origins.','Reject unlisted origins including misleading suffixes and the literal null origin.'],
        [['https://app.example.test','Allowed under the one-origin configuration.'],['https://app.example.test.attacker.test or null','Not allowed.']],
        ['An origin includes scheme, host, and effective port.','A Set of configured canonical origins avoids suffix and regex surprises.'],
        "const allowed=new Set(['https://app.example.test']); const allowOrigin=origin=>typeof origin==='string' && allowed.has(origin);\nFor an allowed credentialed response set Access-Control-Allow-Origin to that exact origin and Access-Control-Allow-Credentials:true; use Vary: Origin when responses depend on Origin. Do not echo an arbitrary string, allow '*' with credentials, or interpret absence/null as automatic trust. This predicate is only a CORS decision, not user authentication or CSRF validation.",
        'Add an explicit local-development origin without changing the production allowlist.'),
    review('CORS','Easy','cors-credentials','Debug a wildcard response on a cookie request',
        'A CORS frontend fetch uses credentials:include while the API sends Access-Control-Allow-Origin:* and Access-Control-Allow-Credentials:true. The browser refuses access. Explain the incompatibility and supply a secure response policy for one trusted frontend without broadening all origin access.',
        'Pair credentialed browser requests with an explicit allowed response origin.',
        ['Return only the specifically authorized origin on credentialed responses.','Keep cookie SameSite/Secure rules and normal authentication independent of CORS.'],
        [['Allowed frontend sends a cookie request','Explicit allowed origin plus credentials header permits browser exposure if other policies pass.'],['Untrusted origin sends the same request','No credentialed read permission; server still enforces authentication/authorization.']],
        ['A wildcard is not a credentialed origin allowlist.','Browser cookie delivery has its own site and security rules.'],
        'Replace wildcard reflection with a configured exact-origin decision and send the matched origin plus Access-Control-Allow-Credentials:true only when allowed. Add Vary: Origin for variable responses.\nKeep fetch credentials settings intentional, and configure cookies for the actual same-site or cross-site deployment. A successful CORS decision does not force browsers to accept/send a cookie blocked by SameSite or third-party-cookie policies. Do not fix a browser error by exposing every caller’s private data to every origin.',
        'Explain why non-browser clients can still call the endpoint.'),
    review('CORS','Easy','cors-preflight','Answer OPTIONS without performing the mutation',
        'A CORS browser preflights a PATCH request using Content-Type and X-CSRF-Token. The server routes OPTIONS into the actual update controller. Design a bounded preflight response that checks allowed origin, method, and headers but never changes business state.',
        'Separate browser capability negotiation from executing an action.',
        ['Validate requested method/header names against explicit lists.','End successful OPTIONS with no business mutation and still authenticate/authorize the actual PATCH.'],
        [['Allowed origin requests PATCH with approved headers','Return the configured allow headers/methods and an empty 204 response.'],['Preflight requests an unapproved method/header','Do not grant permission or invoke the update service.']],
        ['Preflight describes a future request; it is not that request.','Browser preflights ordinarily do not carry the actual application credentials.'],
        'Handle OPTIONS in the CORS boundary before business dispatch. Check Origin, Access-Control-Request-Method, and the case-insensitive requested header names against configured lists, then return only the supported policy and end the response.\nDo not require an authenticated user on the normal browser preflight merely to discover allowed methods, and do not execute the protected action there. The actual PATCH independently requires authentication, CSRF validation where relevant, authorization, and input validation. Test that preflight leaves persistence-call counts at zero.',
        'Define rejection behavior for a valid origin requesting a disallowed header.'),
    review('CORS','Medium','cors-not-csrf','Do not treat blocked response access as prevented action',
        'A CORS-only defense protects a cookie-authenticated endpoint that accepts a simple form POST. An attacker’s page cannot read the response but may still trigger the request. Explain the difference and design server-side CSRF protection for the mutation.',
        'Distinguish browser response sharing from request intent validation.',
        ['Protect mutations with a suitable session-bound CSRF/origin strategy.','Keep GET safe and do not assume every cross-site request is preflighted.'],
        [['Cross-site form POST with no valid CSRF proof','Reject before side effects even if the browser would hide the response.'],['Authorized application POST with valid proof','Process only after normal permission and input checks.']],
        ['Simple cross-origin requests can be sent without preflight.','CORS controls browser exposure of a response, not every possible request side effect.'],
        'Require CSRF protection appropriate to the credential model, for example a session-bound synchronizer token and strict Origin validation for unsafe actions. Enforce intended media types and input schemas without treating those alone as universal CSRF protection.\nUse SameSite cookies as defense in depth and keep state changes out of GET. Continue explicit origin allowlisting for response sharing, but never claim a missing CORS response header proves that an action was not performed. Test a real cross-site form-style request as well as fetch preflight.',
        'Explain how bearer headers supplied explicitly by a trusted client change the CSRF threat model.'),
    review('CORS','Medium','cors-cache','Keep cached CORS responses separated by origin',
        'A CORS endpoint varies allowed response headers by Origin, but a shared cache stores the first response without Vary. Another frontend receives the wrong policy and private data caching is also enabled. Design cache separation and a private-data cache policy.',
        'Align cache keys and response sensitivity with dynamic origin policy.',
        ['Add Vary: Origin when the response/policy varies by origin.','Use a private/no-store policy appropriate to sensitive authenticated responses rather than assuming CORS protects cache contents.'],
        [['Allowed origins A and B request through a cache','A response must not be reused under the wrong origin policy.'],['Sensitive account response','Avoid unintended shared caching regardless of correct CORS headers.']],
        ['CORS headers are part of the cached response representation.','Vary is not an authorization mechanism or a substitute for private cache policy.'],
        'Append Origin to Vary without overwriting existing dimensions. Apply private or no-store cache controls for authenticated sensitive data under the application policy; verify intermediary behavior instead of trusting a header in isolation.\nIf preflight responses vary by requested method/headers, account for those dimensions at any intermediary caching that response. Test multiple origins and authenticated identities through the real cache path. Correct CORS policy does not make a shared cached personalized body safe.',
        'Specify a safe cache policy for a deliberately public static API.'),
    review('CORS','Medium','cors-exposed-header','Expose only the non-sensitive response metadata needed by a client',
        'A CORS frontend needs X-Request-Id and a pagination cursor header but cannot read them from fetch. Developers propose exposing every response header. Design an explicit exposed-header list while preserving the boundary around authentication secrets.',
        'Make cross-origin readable metadata intentional.',
        ['Expose only needed safe response headers.','Do not put bearer/session secrets in public custom headers or assume Set-Cookie becomes script-readable.'],
        [['Allowed client reads X-Request-Id after explicit exposure','It can correlate a request without gaining account secrets.'],['Client tries to read Set-Cookie','Browser protections still prevent treating it as an ordinary exposed header.']],
        ['Allowed request headers and exposed response headers are different policies.','A cursor must not encode private data merely because it is called metadata.'],
        'For an authorized origin configure Access-Control-Expose-Headers: X-Request-Id, X-Next-Cursor and keep the ordinary origin/credential checks intact. Design opaque or safely encoded bounded cursors and never return session credentials through those headers.\nDo not confuse Access-Control-Allow-Headers, which concerns incoming request headers, with response exposure. Test access from a real browser because a server-side HTTP client sees headers without enforcing CORS. Set-Cookie is not a general script-readable response field.',
        'Decide whether a cursor should be signed to bind filters and tenant scope.'),
    review('CORS','Hard','cors-dynamic-tenants','Trust tenant frontend origins only after verified onboarding',
        'A CORS SaaS product supports custom tenant domains. A route echoes any Origin supplied together with a tenant ID query parameter. Design verified domain onboarding, origin-to-tenant mapping, and revocation without permitting an attacker to register another tenant’s trusted browser origin.',
        'Bind dynamic origin policy to verified domain and tenant authority.',
        ['Verify domain control and authorized tenant administration before activation.','Resolve exact origins through server-owned mappings and keep resource authorization independent.'],
        [['Unverified attacker origin includes victim tenantId','No CORS grant and no victim resource access.'],['Tenant removes a verified domain','Invalidate origin policy caches and stop granting new exposure under the stated freshness policy.']],
        ['A query parameter cannot establish domain ownership.','DNS/subdomain lifecycle changes can invalidate earlier trust assumptions.'],
        'Maintain an exact-origin registry populated only by a reviewed domain-control verification and authorized tenant admin workflow. Bind scheme/host/port and tenant ownership explicitly, reject ambiguous mappings, and never infer trust solely from suffixes or user-submitted IDs.\nEnforce authenticated tenant access on actual requests, prevent credentials being confused across tenant origins, and define revocation/cache TTL. Monitor domain expiry/delegation changes and revalidation as appropriate. Test onboarding races, cross-tenant lookups, and a removed domain through the deployment cache path.',
        'Define how an abandoned custom subdomain is deactivated before it can be taken over.'),
    review('CORS','Hard','cors-private-network','Keep server fetch destinations separate from browser origin permissions',
        'A CORS API fetches a URL from the request body and returns the result to an allowed frontend. Developers claim the strict browser Origin allowlist prevents access to internal services. Explain why this does not prevent SSRF and design a constrained server-side fetch capability.',
        'Separate browser sharing policy from server network authority.',
        ['Prefer a fixed resource-ID-to-destination mapping over arbitrary URLs.','Validate destinations and redirects at the network boundary and enforce egress controls.'],
        [['Allowed frontend supplies a loopback or metadata-service URL','The server fetch capability must reject it independently of CORS.'],['Redirect changes a public destination to an internal address','Revalidate each hop or disallow redirects under the policy.']],
        ['The server performs the fetch using its own network privileges.','A malicious or compromised allowed frontend is still untrusted input.'],
        'Restrict the feature to known provider/resource IDs where possible. For necessary URL fetching, use a reviewed destination policy covering schemes, hosts, ports, address resolution, redirects, response size, timeouts, and egress restrictions, including IPv6 and private/metadata ranges.\nPrevent DNS rebinding and resolution/connect mismatches through suitable networking controls rather than a one-time text check alone. Keep CORS as a separate browser response policy. Do not return sensitive internal fetch results merely because the requesting Origin was allowed.',
        'Design a deterministic integration test using controlled public-to-private redirect fixtures.'),
    review('CORS','Hard','cors-observability','Diagnose a CORS failure without weakening the policy',
        'A CORS release breaks only credentialed PATCH requests from one frontend behind a CDN. Propose a diagnostic sequence covering preflight, redirects, cache headers, cookies, actual authentication, and error responses without temporarily enabling wildcard trust.',
        'Use browser and network evidence to isolate the failing policy layer.',
        ['Inspect both preflight and actual response including failures and redirects.','Test approved and disallowed origins and keep secrets out of diagnostic logs.'],
        [['Preflight passes but actual 401 lacks expected allowed-origin headers','Fix intended error-response CORS composition; do not disable authentication.'],['Cookie is absent due to SameSite or browser policy','Diagnose cookie delivery separately from response sharing.']],
        ['A browser CORS message can hide an underlying HTTP error from application JavaScript.','A non-browser curl success does not demonstrate browser enforcement works.'],
        'Capture a redacted browser Network trace: Origin, requested method/header names, preflight status/policy, redirects, actual status, Vary/cache controls, and whether cookies were sent under browser rules. Compare with server request IDs and CDN behavior.\nCheck that approved-origin headers are consistently applied to intended success/error paths, without granting arbitrary origins. Test representative browsers and preflight-cache conditions. Avoid logging cookies/tokens, blanket reflection, disabling Secure, or treating a development proxy as proof the production trust policy is correct.',
        'Create a release acceptance matrix with an allowed origin, a disallowed origin, and an authentication failure.'),

    review('OWASP','Easy','owasp-sql-values','Keep search text out of SQL grammar',
        'An OWASP review finds a search endpoint concatenating a submitted email into SQL text. Explain injection at the code/data boundary and provide a parameterized PostgreSQL-style equality query while keeping tenant scope derived from verified authority.',
        'Use bound values instead of string-built query predicates.',
        ['Bind both tenant and email values separately from SQL text.','Do not treat escaping or frontend validation as the sole injection defense.'],
        [['Email contains an apostrophe or SQL-looking text','It remains one data value, not executable SQL.'],['Authenticated tenant A submits another tenant ID','The server uses verified tenant scope instead.']],
        ['A parameter placeholder stands for a value, not an SQL clause.','Dynamic column/order names need separate fixed allowlists.'],
        "const query={text:'SELECT id,email FROM users WHERE tenant_id=$1 AND email=$2',values:[principal.tenantId,inputEmail]};\nPass the query object to a parameter-supporting driver. Validate input size/format for the product contract, but do not interpolate it into text after validation. Keep database credentials least-privileged and return an allowlisted DTO. Parameterization does not replace tenant authorization.",
        'Design an allowlisted sort field without allowing arbitrary SQL keywords.'),
    review('OWASP','Easy','owasp-output-context','Render untrusted comments as text',
        'An OWASP review finds stored comments inserted into a page through raw HTML. Design a safe plain-text rendering path and explain why a general blacklist of script tags does not handle all HTML/URL/attribute injection contexts.',
        'Match output handling to its rendering context.',
        ['Use text rendering or framework escaping for plain comments.','Do not recommend raw HTML insertion of untrusted data; sanitize only under a justified rich-text contract.'],
        [['Comment contains markup-like text','It appears as text rather than executing.'],['Comment is later placed in a URL attribute','Apply a separate allowed-scheme/URL policy instead of assuming text escaping validates a URL.']],
        ['Encoding prevents data being interpreted as markup in a specific context.','Rich HTML needs a maintained sanitizer configured for the intended elements and attributes.'],
        'For plain comments assign textContent or render a React text child such as <p>{comment}</p>; do not use dangerouslySetInnerHTML for untrusted plain text. Validate URL schemes separately when using data as links.\nIf rich text is a real requirement, use a maintained allowlist sanitizer and prevent unsafe transformations after sanitization. Add CSP as defense in depth, not as permission to keep an unsafe sink. Test stored as well as reflected inputs and confirm safe handling in every output context.',
        'Explain why a sanitized HTML fragment may still be unsafe when reused as JavaScript source.'),
    review('OWASP','Easy','owasp-secret-errors','Return safe errors without losing internal diagnostics',
        'An OWASP review finds API exceptions serialized with stack traces, database URLs, and request bodies. Design a public error contract with request correlation and redacted internal logging, preserving useful operational evidence without leaking credentials.',
        'Separate user-facing errors from restricted diagnostics.',
        ['Use safe stable public codes and a server-generated request ID.','Redact passwords, tokens, cookies, and connection secrets from logs.'],
        [['Database throws a credential-bearing message','Client receives a generic server-error code, not the raw exception.'],['Operator investigates the request ID','Restricted diagnostics identify the operation and failure category with secrets redacted.']],
        ['Serializing an Error object or request object can expose more than its message.','Logs are another sensitive data store with access and retention controls.'],
        'Map known client errors to safe messages and unknown exceptions to a generic internal-error response carrying a correlation ID. Log controlled operation/category/context under restricted access and retention; avoid dumping raw requests, authorization headers, session cookies, or connection strings.\nTest nested error causes and structured logging redaction, not just the top-level message. Do not suppress every diagnostic to hide a leak; preserve safe evidence and alerts so operators can distinguish outages, invalid inputs, and attack patterns.',
        'Define a redaction test for nested authorization headers.'),
    review('OWASP','Medium','owasp-upload','Constrain uploads before processing and serving them',
        'An OWASP review finds uploads accepted with only a filename extension check and then served from the application origin as active content. Design size/type/storage/serving controls and explain why client MIME type is not proof of file contents.',
        'Treat uploaded bytes and names as untrusted data across ingestion and delivery.',
        ['Enforce size/count limits, allowed content types with appropriate inspection, and safe generated storage names.','Store outside executable paths and serve with a policy preventing unintended active-content execution.'],
        [['Client labels arbitrary bytes as image/png','Do not trust that header alone; inspect/decode under bounded processing policy.'],['Filename contains traversal components','Ignore it for storage path construction and use a server-owned identifier.']],
        ['Validation must cover bytes, metadata, processing cost, and later delivery.','Image/archive processing can consume resources even after a small initial upload.'],
        'Authenticate/authorize uploads, bound body size/count, allowlist supported formats, and inspect or decode with maintained bounded tooling. Generate storage keys independent of user filenames and prevent traversal, execution, or overwrite.\nUse private storage and scoped download authority; serve potentially active content from an appropriate isolated origin or as attachment with safe headers according to the feature contract. Apply malware scanning where justified, archive expansion limits, quotas, and cleanup for failed uploads. A successful extension/MIME check alone is not a safety guarantee.',
        'Define a quarantine state and how a rejected upload is removed safely.'),
    review('OWASP','Medium','owasp-reset-token','Make password reset credentials short-lived and single-use',
        'An OWASP reset flow uses a predictable account ID in the URL and does not expire or consume it. Design a cryptographically random reset credential with protected storage, generic request responses, and atomic consumption coupled to the password change.',
        'Treat account recovery as a scoped credential lifecycle.',
        ['Store a verifier for a high-entropy token with account, purpose, and expiry.','Atomically consume it with the credential update and apply a session-revocation policy.'],
        [['Valid unused token before expiry','Permit the scoped password change and consume the token.'],['Token expired, already used, or submitted for another account','Reject without changing credentials.']],
        ['A user ID identifies an account; it is not recovery authority.','A successful precheck followed by an unconditional reset leaves a replay race.'],
        'Generate a high-entropy token using a cryptographic RNG, store only its secure digest/verifier with a short expiry and reset purpose, and deliver through the verified recovery channel. Use a configured HTTPS reset origin rather than an untrusted Host header.\nValidate and consume atomically with the new password verifier, revoke other reset credentials as appropriate, and apply the documented session invalidation policy. Return generic reset-request responses and rate-limit issuance/verification. Keep tokens out of logs/referrers and notify the account through a trusted channel.',
        'Test two concurrent submissions of the same reset token.'),
    review('OWASP','Medium','owasp-dependency','Triage a reachable dependency vulnerability',
        'An OWASP dependency audit flags a vulnerable document parser used by public uploads. A major upgrade fixes it but changes size limits. Design a remediation sequence covering reachability, migration validation, lockfile review, and a safe temporary mitigation if upgrade is delayed.',
        'Connect dependency advisories to actual exposed application paths.',
        ['Trace installed version and dependency path to the vulnerable feature.','Validate the fixed artifact and migration behavior rather than blindly forcing every update.'],
        [['Public upload reaches the affected parser operation','Prioritize remediation or disable/restrict that feature until safely fixed.'],['Upgrade changes parser defaults','Run normal, malformed, oversized, and resource-exhaustion regression cases.']],
        ['A package name alone does not establish exploit prerequisites.','An audit report is one signal, not a complete security assessment.'],
        'Record affected versions, prerequisites, dependency chain, and untrusted input reachability. Upgrade through a reviewed lockfile change and inspect breaking changes plus integrity/provenance controls appropriate to the build.\nTest the actual packaged runtime and bounded parser behavior. If temporarily blocked, disable or isolate the reachable capability with an owner and deadline; do not dismiss it solely because it is transitive. Repeat advisory checks and monitor residual risk. A clean audit does not prove authorization or business logic correct.',
        'Define acceptance evidence for a temporary parser isolation boundary.'),
    review('OWASP','Hard','owasp-threat-model','Model trust boundaries for an AI document assistant',
        'An OWASP design review covers user document uploads, chunk storage, a vector index, retrieval, model output, and tools. Build a threat model for cross-tenant retrieval and instruction-like content inside documents without treating retrieved text as trusted control instructions.',
        'Trace sensitive data and authority through every pipeline boundary.',
        ['Scope ingestion, retrieval, citations, deletion, and tools to verified authority.','Keep document/model text separate from deterministic tool permissions and output handling.'],
        [['Tenant A embeds text requesting tenant B files','Retrieval and tools remain scoped to A independently of that text.'],['A source document is deleted or access revoked','Derived chunks/cache/search state follow a defined invalidation policy.']],
        ['Prompt text does not establish tool authority.','Data flow diagrams should include derived stores, logs, and external model providers.'],
        'Map actors, stores, services, credentials, and trust boundaries. Validate uploaded content and bound processing; attach authoritative tenant/source metadata and enforce it in retrieval and source lookup. Treat retrieved instructions as untrusted evidence.\nValidate every tool call and authorize its resource/action independently of model output; encode/sanitize generated output for its actual display context. Define deletion propagation, provider data handling, audit redaction, quotas, and failure tests. Threat modeling identifies controls and residual risk; it is not a guarantee that a prompt can prevent all malicious instructions.',
        'Write a negative integration test for cross-tenant citation resolution.'),
    review('OWASP','Hard','owasp-business-logic','Prevent coupon replay across concurrent checkouts',
        'An OWASP business-logic review finds a one-use coupon checked by a read and marked used only after payment. Concurrent checkouts both obtain the discount. Design an atomic claim, bounded reservation expiry, and payment reconciliation without blindly releasing a coupon after an uncertain payment outcome.',
        'Enforce economic invariants under concurrency and retries.',
        ['Claim coupon eligibility atomically with an operation identity.','Define reservation, commit, expiry, and uncertain-payment recovery states.'],
        [['Two checkouts race for one-use coupon','At most one active allowed claim wins.'],['Payment times out after possible success','Reconcile by operation/provider identity before releasing or consuming again.']],
        ['Valid individual requests can violate a shared business rule together.','Timeout is not proof that payment failed.'],
        'Model coupon state and usage with an atomic unique/conditional claim scoped to account and campaign policy. Tie it to a stable checkout/payment operation and a documented reservation deadline.\nFinalize consumption with the committed order result or reconcile the provider outcome; retry safely using idempotency. Release only when the state machine proves the reservation can be abandoned, using fencing/version checks to stop stale workers. Test concurrent claims, lost acknowledgements, expiry, and duplicate callbacks. Input validation alone does not enforce this cross-request invariant.',
        'Define how refunds affect coupon eligibility without rewriting original redemption history.'),
    review('OWASP','Hard','owasp-security-regression','Turn access-control findings into negative release tests',
        'An OWASP review finds that list routes are owner-scoped but exports, bulk updates, and direct download URLs bypass checks. Design a regression matrix that inventories alternate paths and verifies denial and side-effect absence, rather than testing only the visible browser button.',
        'Cover every route and reusable operation that exposes a protected resource.',
        ['Include direct IDs, nested resources, bulk operations, exports, and derived download capabilities.','Assert denial, safe error data, and zero unauthorized writes or disclosures.'],
        [['User A submits a mixed bulk list with A and B resources','Apply a documented atomic rejection or per-item policy without exposing/altering B.'],['User follows an old export link after permission revocation','Enforce the declared capability expiry/revocation policy and do not serve an unrestricted private file.']],
        ['A hidden button is not an enforcement point.','Test privileged and ordinary roles with valid but unauthorized IDs.'],
        'Inventory routes, services, jobs, caches, file-serving paths, and capability URLs for each resource action. Build actor/resource/action matrices including unauthenticated, same-owner, other-owner, removed-member, and service identities.\nUse integration fixtures with distinct tenants and verify response fields plus persistence/audit effects, not status alone. Test bulk partial-failure semantics and direct service entry points. Add the discovered bypass as a permanent negative test and review changes to new routes against the matrix. A fixed frontend affordance is not sufficient remediation.',
        'Define how the matrix is updated when a new export format is introduced.'),

    review('Rate Limiting','Easy','rate-response','Return a useful quota-exceeded response',
        'A Rate Limiting endpoint returns 500 after a client exhausts a request quota. Define a 429 contract with a bounded Retry-After value and explain how clients should retry without assuming the next attempt is guaranteed to succeed.',
        'Distinguish quota exhaustion from unexpected server failure.',
        ['Use 429 for an exhausted client quota and a correct retry delay when known.','Do not expose another account’s quota state or recommend immediate retry loops.'],
        [['Quota resets in 12 seconds','429 with Retry-After: 12 under a delay-seconds contract.'],['Client retries before budget replenishes','It may receive another controlled 429, not a stack trace.']],
        ['Retry-After can convey delay, not permission to bypass other checks.','Clients need bounded backoff and jitter to avoid synchronized bursts.'],
        'Return a safe structured QUOTA_EXCEEDED error with status 429 and a nonnegative rounded-up delay in seconds when the limiter has a reliable reset estimate. Keep retry metadata scoped to the caller and avoid private account-existence details.\nClients should wait, use bounded jitter/backoff, and respect the overall deadline. A later request must still pass authentication, authorization, and the current limiter decision. Use a distinct controlled availability outcome for a broken mandatory limiter store rather than mislabeling every store exception as user quota exhaustion.',
        'Test delay rounding when the remaining wait is 1.2 seconds.'),
    review('Rate Limiting','Easy','rate-key','Choose independent caller and account budgets',
        'A Rate Limiting login endpoint uses only IP addresses. Office users share one NAT while an attacker rotates many addresses against one account. Design layered source and account budgets without letting an unverified username bypass limits or trivially lock out a victim forever.',
        'Select abuse keys according to the protected resource and attack pattern.',
        ['Combine bounded source/network and normalized account-target controls.','Avoid permanent victim lockout and keep public outcomes from confirming account existence.'],
        [['Many legitimate users share an office IP','Use measured network policy and additional identities rather than one tiny global IP allowance.'],['Distributed attempts target one account','Account-target controls still observe pressure across IPs.']],
        ['IP is neither a stable user identity nor useless telemetry.','Account-target state needs size limits because attackers can invent names.'],
        'Apply layered request budgets: coarse network/source protection, normalized account-target failure controls, and session/device signals where trustworthy. Use controlled temporary delays/challenges and recovery paths rather than indefinite lockout from attacker-triggered failures.\nNormalize keys consistently, limit attacker-driven cardinality/retention, and avoid storing raw sensitive identifiers unnecessarily in telemetry. Treat unverified target names as abuse buckets, not authenticated authority. Test NAT fairness, IP rotation, random-account floods, and recovery without exposing whether an account exists.',
        'Describe how to monitor false positives without logging submitted passwords.'),
    review('Rate Limiting','Easy','rate-fixed-boundary','Explain a fixed-window boundary burst',
        'A Rate Limiting policy permits ten requests in each one-minute fixed window. A client sends ten at second 59.9 and ten at second 60.1. Explain the allowed burst and choose whether a sliding-window or token-bucket policy better matches a smoother requirement.',
        'Match limiter algorithms to the intended burst contract.',
        ['Recognize that the fixed-window policy can admit both groups.','State whether short bursts are allowed before replacing the algorithm.'],
        [['Ten requests just before and ten just after reset','Twenty can pass in a very short interval under fixed-window semantics.'],['Requirement is at most ten in any rolling minute','A correct sliding-window design is closer than the simple fixed-window counter.']],
        ['A wall-clock window is not every possible interval of the same length.','Token buckets intentionally allow a bounded accumulated burst.'],
        'Document the fixed-window behavior honestly: reset boundaries can admit consecutive full quotas. If any rolling-minute maximum is required, choose a validated sliding-window algorithm with atomic shared state and a defined precision/storage trade-off.\nIf short bursts are acceptable with a long-run rate, use a token bucket with explicit capacity/refill. Benchmark hot-key cost and storage; an approximate rolling counter needs an error bound rather than a claim of exact equivalence. Test the reset boundary and not just evenly spaced requests.',
        'Define a peak-concurrency limit that complements either rate algorithm.'),
    review('Rate Limiting','Medium','rate-token-bucket','Trace a token bucket with an injected clock',
        'A Rate Limiting token bucket has capacity five and refills one token per second. Initially full at time zero, it receives five unit-cost requests immediately and another at 0.5 seconds. Specify decisions and refill arithmetic, including a clock value that moves backwards.',
        'Model bounded burst capacity and elapsed-time refill deterministically.',
        ['Cap tokens at capacity and require enough tokens for the full request cost.','Use a monotonic time source or explicit backwards-clock policy and atomic state ownership.'],
        [['Five requests at t=0 followed by one at t=0.5','First five pass; the last waits because only 0.5 tokens refilled.'],['Next request at t=1 after those decisions','One full token is available and may be consumed.']],
        ['Fractional refill state prevents unnecessary rounding loss.','An in-memory arithmetic model is not a distributed atomic limiter.'],
        'At each decision compute elapsed=max(0,now-last), available=min(capacity,tokens+elapsed*rate), and permit only if available>=cost; subtract the cost only on permit. Preserve the effective nondecreasing timestamp according to the clock policy.\nInject a monotonic clock for tests and serialize updates within the state owner. Validate positive capacity/rate/cost and finite numbers. For multiple replicas implement refill-and-consume atomically in a shared store or choose a single owner; reading then separately writing the bucket races. Bound bucket count and expiry.',
        'Extend the trace to a request costing three tokens.'),
    review('Rate Limiting','Medium','rate-atomic-store','Make a distributed counter and expiry one decision',
        'A Rate Limiting service increments a Redis key and sets expiry in a separate command. A crash between them leaves a permanent counter, while concurrent read-check-write logic can admit too many requests. Design a vetted atomic script/function or maintained store adapter for the quota.',
        'Keep quota updates and lifecycle atomic across replicas.',
        ['Perform check/increment/window-expiry semantics in one atomic store operation.','Define TTL/reset behavior explicitly and inspect the chosen adapter’s failure handling.'],
        [['Process dies after the store operation','No counter exists indefinitely because its expiry was skipped.'],['Two replicas race on the last permitted request','At most the policy’s remaining atomic budget is granted.']],
        ['A local mutex cannot coordinate multiple processes.','An INCR call alone does not specify your entire window and rejection semantics.'],
        'Use a maintained limiter adapter or reviewed atomic Redis script/function that owns counter initialization, increment/check, and expiry under one defined algorithm. Return the decision and reset metadata from that same operation.\nValidate the store deployment, key expiry, serialization, and replica/failover consistency assumptions. Do not claim perfect global enforcement across failover without validating its guarantees. Test parallel last-slot requests, initialization crashes, expiry, and store outage. Keep keys bounded and scoped to the intended authenticated or abuse identity.',
        'Specify whether rejected attempts increment the counter and why.'),
    review('Rate Limiting','Medium','rate-cost-budget','Budget expensive endpoints by work rather than request count',
        'A Rate Limiting API treats a tiny metadata read and a thousand-page AI document analysis as one request each. Design per-operation weighted quotas plus a concurrency and input-size boundary so a small request count cannot exhaust compute or spend.',
        'Limit resource consumption according to measured work and caller scope.',
        ['Bound input size and simultaneous expensive jobs before admission.','Reserve a justified estimated cost and reconcile actual usage under an explicit accounting rule.'],
        [['One request submits an oversized document','Reject before expensive parsing/model work.'],['Caller has request tokens but no compute quota','Do not admit the expensive job merely because request count is low.']],
        ['Request rate, concurrent work, and cumulative spend are different budgets.','Reservation and refund rules need operation IDs to avoid double accounting.'],
        'Define operation classes with bounded input/output and measured cost weights. Check account/tenant spend, per-operation rate, and active-job capacity before accepting expensive work; reserve budget atomically with a stable operation identity.\nReconcile actual cost and release unused reservation under a replay-safe rule. Handle cancellations and uncertain external charges without blindly refunding work that may have been consumed. Return safe quota/overload feedback and provide an abuse-resistant workflow for legitimate larger jobs.',
        'Design a test for duplicate job submission and duplicate usage callbacks.'),
    review('Rate Limiting','Hard','rate-outage-policy','Choose limiter-store failure behavior by operation risk',
        'A Rate Limiting store outage currently disables all quotas silently. Compare sign-in, password reset, paid AI generation, and cheap public reads. Design explicit failure policies and a bounded local fallback only where the risk and aggregate capacity justify it.',
        'Avoid turning an availability failure into unbounded abuse authority.',
        ['Fail closed or shed load for high-risk/expensive operations when mandatory budgets cannot be checked.','For any allowed degraded path, cap per-replica and aggregate risk and expose monitoring signals.'],
        [['Quota store fails during paid generation admission','Do not admit unlimited billable jobs; return controlled unavailability under the required-budget policy.'],['Cheap public reads have an approved local emergency cap','Degrade only within that cap and document replica multiplication.']],
        ['Fail-open and fail-closed are product risk decisions, not universal defaults.','A local fallback budget times replica count can exceed the intended global allowance.'],
        'Classify operations by abuse impact, confidentiality, and cost. Require authoritative budgets for password/reset/paid work as specified and return a controlled availability error when they cannot be evaluated.\nFor approved low-risk reads, use bounded in-process emergency rate/concurrency limits with a known fleet-size ceiling and circuit breaker, not unlimited fail-open. Alert on degraded mode and restore shared enforcement safely. Test network partitions, stale replica data, reconnect bursts, and whether retry clients amplify overload. Keep this policy separate from authentication-store failure handling.',
        'Define the user-facing difference between quota exhaustion and limiter unavailability.'),
    review('Rate Limiting','Hard','rate-proxy-spoof','Prevent forwarded headers from selecting a fresh rate key',
        'A Rate Limiting gateway keys requests by the first X-Forwarded-For value even when direct clients can reach it. An attacker changes the header on every request. Design trusted-proxy extraction and IPv4/IPv6 key normalization without treating IP as authenticated identity.',
        'Build abuse keys from a verified network path.',
        ['Trust only configured proxy hops and require edge header sanitation.','Normalize addresses consistently and choose IPv6 aggregation/fairness policy deliberately.'],
        [['Direct attacker sends arbitrary forwarding headers','They cannot choose an unlimited series of trusted source keys.'],['Legitimate IPv6 client rotates addresses in a delegated range','A measured subnet policy may help while avoiding unjustified collateral blocking.']],
        ['A header becomes trustworthy only through the network boundary that created it.','Different ingress paths can invalidate a fixed hop-count assumption.'],
        'Restrict backend ingress and configure proxy trust to the actual verified topology. Have the edge replace untrusted forwarding headers, then use the framework’s correctly configured client-address resolution rather than parsing the first header blindly.\nCanonicalize IPv4/IPv6 and define whether to aggregate IPv6 prefixes based on measured abuse and fairness requirements. Combine network keys with authenticated account/tenant budgets. Test spoofed chains, multiple ingress paths, mapped IPv4 forms, NAT groups, and legitimate IPv6 rotation; do not solve evasion by permanently blocking whole populations without evidence.',
        'Define a migration test when a new CDN or ingress path is added.'),
    review('Rate Limiting','Hard','rate-fair-scheduling','Keep one tenant from consuming the whole worker pool',
        'A Rate Limiting design enforces a generous global request quota but one tenant fills every long-running worker slot. Design tenant-aware fair admission with global safety bounds, bounded queues, cancellation, and starvation monitoring without trusting a body tenantId.',
        'Combine fairness and capacity limits across independent tenants.',
        ['Derive tenant scope from verified authority and enforce both global and per-tenant capacity.','Bound queue length/wait and choose an explicit fair scheduling policy.'],
        [['Tenant A submits hundreds of expensive jobs','A remains within its active/queued allocation; tenant B can still make progress under policy.'],['Tenant cancels queued or running work','Release accounting only when the owned job state proves the reservation can be released.']],
        ['A rate budget does not ensure fair sharing of long-lived resources.','Fair scheduling needs observable queue wait and starvation behavior, not just a concurrency number.'],
        'Use authenticated tenant keys, a global active-work ceiling, per-tenant active/queued limits, and a reviewed fair scheduler such as weighted round-robin with documented weights. Bound queue wait and reject overflow before retaining unlimited payloads.\nUse job identities and atomic state transitions to coordinate cancellation, timeout, completion, and budget release exactly according to the accounting contract. Track tenant wait percentiles, rejected work, utilization, and starvation; test a noisy tenant alongside a small tenant under slow-worker conditions. Horizontal scaling must preserve the intended fleet-wide allocations.',
        'Specify how premium weights change service without allowing starvation of ordinary tenants.')
];
